a<-commandArgs(TRUE);if(length(a)<2)stop("Usage: validate_predictions.R <pred.csv> <report.csv>");d<-read.csv(a[1],check.names=FALSE);if(!all(c("Time","Event")%in%names(d)))stop("Require Time/Event");m<-setdiff(names(d),c("ID","Time","Event"));z<-do.call(rbind,lapply(m,function(n){x<-d[[n]];isrisk<-grepl("__risk__[0-9.]+$",n);data.frame(column=n,n=nrow(d),missing=sum(is.na(x)),nonfinite=sum(!is.finite(x),na.rm=TRUE),unique=length(unique(x)),min=suppressWarnings(min(x,na.rm=TRUE)),max=suppressWarnings(max(x,na.rm=TRUE)),risk_range_ok=!isrisk||all(x>=0&x<=1,na.rm=TRUE))}));write.csv(z,a[2],row.names=FALSE);print(z,row.names=FALSE);if(any(z$missing>0|z$nonfinite>0|z$unique<2|!z$risk_range_ok))quit(status=2L)
